func canonicalError(code string) (string, string) {
	if entry, ok := errorCatalog[code]; ok {
		return entry.code, entry.message
	}
	for _, entry := range errorCatalog {
		if entry.code == code {
			return entry.code, entry.message
		}
	}
	// These errors contain runtime details, which must not become public codes.
	for _, entry := range []struct{ prefix, code, message string }{
		{"invalid or repeated SDK ", "invalid_sdk_order", "Lista SDK-urilor conține o versiune necunoscută sau repetată."},
		{"cannot apply CEAS firewall", "ceas_firewall_failed", "Regulile firewall pentru modul CEAS offline nu au putut fi aplicate. Verificați detaliile Windows."},
		{"source filename does not match source identity:", "tdx_source_identity_mismatch", "Fișierul TDX nu corespunde datelor sursă. Verificați contractul original, numele calculatorului și adresa IP:port a UM."},
		{"reader or card unavailable (state ", "reader_or_card_unavailable", "Terminalul sau cardul nu este disponibil. Verificați conexiunea și prezența cardului."},
		{"SCardEstablishContext:", "pcsc_context_failed", "Serviciul Windows pentru cititoare de carduri nu poate fi accesat."},
		{"SCardListReaders:", "pcsc_list_readers_failed", "Windows nu a putut furniza lista terminalelor de citire carduri."},
		{"SCardGetStatusChange:", "pcsc_status_failed", "Starea terminalului de citire carduri nu poate fi verificată."},
	} {
		if strings.HasPrefix(code, entry.prefix) {
			return entry.code, entry.message
		}
	}
	if code != "" && !strings.ContainsAny(code, " \r\n:/\\") {
		return code, ""
	}
	return "internal_error", errorCatalog["internal_error"].message
}

func publicErrorCode(code string, sdk int) string {
	code, _ = canonicalError(code)
	if code == "sdk_error" && sdk != 0 {
		return fmt.Sprintf("ECARD_SDK_%d", -sdk)
	}
	return "ECARD_" + strings.ToUpper(code)
}
